import {
  ChangeDetectionStrategy, Component, TemplateRef, ViewEncapsulation,
  computed, effect, input, model, output, signal, untracked, viewChild,
} from '@angular/core';
import { NgTemplateOutlet } from '@angular/common';
import { FormsModule } from '@angular/forms';
import {
  TablerIconComponent, IconDotsVertical, IconDownload, IconLayoutList,
  IconFileImport, IconPrinter, IconColumns3, IconArrowsSort, IconSettings, IconX,
  IconPlus, IconMathFunction,
} from '@tabler/icons-angular';
import { NzDropDownModule } from 'ng-zorro-antd/dropdown';
import { NzMenuModule } from 'ng-zorro-antd/menu';

import { HrmListPage, HrmListPageTabs } from '../enterprise-data/hrm-list-page';
import { HrmDataView, HrmDataViewMode } from '../enterprise-data/hrm-data-view';
import { HrmGridColumn, HrmGridSort } from '../enterprise-data/hrm-grid';
import { HrmQuickFilter } from '../data-entry/hrm-quick-filter';
import { HrmColumnManager } from '../enterprise-data/hrm-column-manager';
import { HrmColumnInspector } from '../enterprise-data/hrm-column-inspector';
import { HrmFormulaBuilder } from '../enterprise-data/hrm-formula-builder';
import { HrmSortConfig, HrmSortColumn } from '../enterprise-data/hrm-sort-config';
import { HrmButton } from '../general/hrm-button';
import { HrmInput } from '../data-entry/hrm-input';
import { HrmSegmented } from '../data-entry/hrm-segmented';
import {
  HrmColumnDef, HrmColumnGroup, HrmRowGroupLevel, hrmAutoAlign,
} from '../enterprise-data/hrm-data-config.types';

type Row = Record<string, unknown>;

/** 1 bộ lọc nhanh (pill) trên toolbar workspace — nguồn cho <hrm-quick-filter>. */
export interface HrmWorkspaceQuickFilter {
  /** Khoá định danh, làm key trong quickFilterValues. */
  key: string;
  /** Nhãn pill (VD "Trạng thái"). */
  label: string;
  /** Đơn vị đếm khi chọn ≥2 (VD "trạng thái" → "2 trạng thái"). */
  unit?: string;
  /** Bật ô tìm trong panel. Mặc định true. */
  searchable?: boolean;
  /** Danh mục lựa chọn. */
  options: { value: string; label: string }[];
}

/**
 * hrm-data-workspace — TEMPLATE MẪU "Không gian dữ liệu": gói dàn nhạc toolbar + cấu hình
 *  (đang inline trong nhiều màn danh sách) vào 1 component DS tái dùng. Ghép sẵn:
 *  page-header (hrm-list-page) → segmented đổi chế độ → toolbar 2 trạng thái (tìm + lọc nhanh +
 *  Nhóm dữ liệu / Xuất / ⋮) → bảng đa chế độ (hrm-data-view) → overlay Cấu hình cột (ColumnManager +
 *  Inspector) + dialog Cấu hình sắp xếp (SortConfig). Sửa template ⇒ mọi màn dùng template đồng bộ.
 *
 *  Consumer chỉ truyền columns/data/quickFilters/flags + điền slot là có full feature.
 *  Định nghĩa cột (columns) là HrmColumnDef; cell render do consumer cấp qua cellTemplates (map key→template)
 *  + computedCell (ô mặc định cho cột tính toán). Toàn token → tự Light/Dark.
 *
 *  ⚠ ViewEncapsulation.None (như các component enterprise-data khác) → mọi class riêng PREFIX 'hdw-'
 *     để không đụng style toàn cục; selector .ant-btn (render bởi hrm-button) áp trực tiếp, không ::ng-deep.
 *
 *  Slot (ng-content, project vào hrm-list-page):
 *   [wsHeaderActions] → cạnh segmented ở [headerActions]
 *   [wsTopCard]       → card trên toolbar+bảng ([lpTabs], vd AI card)
 *   [wsFilterPanel]   → sau quick-filter trong hàng toolbar trái (nút/panel "Bộ lọc")
 *   [wsToolbarExtra]  → trước cụm nút baked ở hàng toolbar phải (nút domain)
 *   [wsMenuExtra]     → mục ⋮ thêm (cuối menu, sau divider)
 *   [wsBulkActions]   → hiện khi có chọn (thay cụm nút chuẩn)
 *   [wsDetail]        → [lpDetail] (chi tiết master cạnh danh sách)
 */
@Component({
  selector: 'hrm-data-workspace',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  imports: [
    NgTemplateOutlet, FormsModule, TablerIconComponent, NzDropDownModule, NzMenuModule,
    HrmListPage, HrmListPageTabs, HrmDataView, HrmQuickFilter,
    HrmColumnManager, HrmColumnInspector, HrmFormulaBuilder, HrmSortConfig, HrmButton, HrmInput, HrmSegmented,
  ],
  template: `
    <hrm-list-page
      [title]="title()" [subtitle]="subtitle()"
      [total]="total()" [(pageIndex)]="pageIndex" [(pageSize)]="pageSize"
      [showSizeChanger]="showSizeChanger()" [panel]="mode() === 'table'">

      <!-- Cụm điều khiển cạnh tiêu đề: segmented đổi chế độ (nếu >1) + slot domain. -->
      <div headerActions class="hdw-hdr">
        @if (modes().length > 1) {
          <hrm-segmented [options]="segmentOptions()" [ngModel]="mode()"
            (ngModelChange)="mode.set($any($event))" size="md" />
        }
        <ng-content select="[wsHeaderActions]" />
      </div>

      <!-- Card trên toolbar+bảng (AI card…) qua slot tabs của list-page. -->
      <div lpTabs><ng-content select="[wsTopCard]" /></div>

      <!-- Toolbar TRÁI: bình thường = tìm + lọc nhanh + panel lọc; CÓ CHỌN = đếm + bỏ chọn. -->
      <div filters class="hdw-tbx">
        @if (selectedKeys().length === 0) {
          @if (searchable()) {
            <hrm-input class="hdw-search" [ngModel]="search()" (ngModelChange)="search.set($event)"
              [placeholder]="searchPlaceholder()" />
          }
          @for (qf of quickFilters(); track qf.key) {
            <hrm-quick-filter [label]="qf.label" [unit]="qf.unit || ''"
              [searchable]="qf.searchable ?? true" [options]="qf.options"
              [value]="qfValue(qf.key)" (valueChange)="setQf(qf.key, $event)" />
          }
          <ng-content select="[wsFilterPanel]" />
        } @else {
          <button type="button" class="hdw-clear" [attr.aria-label]="clearSelectionLabel()"
            (click)="selectedKeys.set([])">
            <tabler-icon [icon]="icX" [size]="16" />
          </button>
          <span class="hdw-count">{{ selectedLabel() }} <b>{{ selectedKeys().length }}</b> {{ bulkUnit() }}</span>
        }
      </div>

      <!-- Toolbar PHẢI: bình thường = slot extra + Nhóm/Xuất/⋮; CÓ CHỌN = slot bulk. -->
      <div actions class="hdw-tbx">
        @if (selectedKeys().length === 0) {
          <ng-content select="[wsToolbarExtra]" />
          @if (groupable() && mode() === 'table') {
            <hrm-button variant="default" class="hdw-grp" [class.hdw-sel]="showGroupPanel() || rowGroups().length > 0"
              [attr.aria-pressed]="showGroupPanel() || rowGroups().length > 0" (click)="showGroupPanel.set(!showGroupPanel())">
              <tabler-icon [icon]="icGroup" [size]="18" /> {{ groupLabel() }}
              @if (rowGroups().length) { <span class="hdw-badge">{{ rowGroups().length }}</span> }
            </hrm-button>
          }
          @if (exportable()) {
            <hrm-button variant="default" (click)="exportClick.emit()">
              <tabler-icon [icon]="icDownload" [size]="18" /> {{ exportLabel() }}
            </hrm-button>
          }
          @if (hasMenu()) {
            <button type="button" class="hdw-more" [attr.aria-label]="moreLabel()"
              nz-dropdown [nzDropdownMenu]="wsMenu" nzTrigger="click" nzPlacement="bottomRight">
              <tabler-icon [icon]="icMore" [size]="18" />
            </button>
          }
        } @else {
          <ng-content select="[wsBulkActions]" />
        }
      </div>

      <hrm-data-view
        [columns]="gridCols()" [data]="data()" [rowKey]="rowKey()"
        [modes]="modes()" [(mode)]="mode"
        [selectable]="selectable()" [selectedKeys]="selectedKeys()" (selectedKeysChange)="selectedKeys.set($event)"
        [tableMinWidth]="tableMinWidth()" [size]="size()"
        [customizable]="false" [reorderable]="false"
        [(sortLevels)]="sortLevels" [(hiddenKeys)]="hiddenKeys" [(rowGroups)]="rowGroups" [(showGroupPanel)]="showGroupPanel"
        [columnGroups]="columnGroups()"
        [groupLabelFormatter]="groupLabelFormatter()"
        [cardTemplate]="cardTemplate()" [boardCardTemplate]="boardCardTemplate()"
        [groupBy]="groupBy()" [boardGroups]="boardGroups()" [boardAddLabel]="boardAddLabel()"
        [startField]="startField()" [endField]="endField()" [progressField]="progressField()"
        [ganttLabelField]="ganttLabelField()" [ganttHeader]="ganttHeader()" [ganttDateHeader]="ganttDateHeader()"
        [ganttLabelTemplate]="ganttLabelTemplate()" [ganttBarTone]="$any(ganttBarTone())"
        (openRecord)="rowClick.emit($event)" (boardAdd)="boardAdd.emit($event)" (groupChange)="groupChange.emit($event)" />

      <!-- Chi tiết master cạnh danh sách. -->
      <ng-content select="[wsDetail]" ngProjectAs="[lpDetail]" />
      <!-- Text phân trang tuỳ consumer (vd "Hiển thị X-Y trong Z"). -->
      <ng-content select="[wsPagerInfo]" ngProjectAs="[pagerInfo]" />
    </hrm-list-page>

    <!-- Menu ⋮ — thao tác phụ (import/print) + cấu hình (cột/sắp xếp/biểu mẫu) + slot domain. -->
    <nz-dropdown-menu #wsMenu="nzDropdownMenu">
      <ul nz-menu class="hdw-menu">
        @if (hasMenuTop()) {
          <ng-content select="[wsMenuTop]" />
          @if (hasMenu()) { <li nz-menu-divider></li> }
        }
        @if (importable()) {
          <li nz-menu-item (click)="importClick.emit()"><tabler-icon [icon]="icImport" [size]="16" /> {{ importLabel() }}</li>
        }
        @if (printable()) {
          <li nz-menu-item (click)="printClick.emit()"><tabler-icon [icon]="icPrint" [size]="16" /> {{ printLabel() }}</li>
        }
        @if ((importable() || printable()) && (columnConfig() || sortConfig() || formConfig())) {
          <li nz-menu-divider></li>
        }
        @if (columnConfig()) {
          <li nz-menu-item (click)="colOpen.set(true)"><tabler-icon [icon]="icColumns" [size]="16" /> {{ columnConfigLabel() }}</li>
        }
        @if (sortConfig()) {
          <li nz-menu-item (click)="sortOpen.set(true)"><tabler-icon [icon]="icSort" [size]="16" /> {{ sortConfigLabel() }}</li>
        }
        @if (formConfig()) {
          <li nz-menu-item (click)="formConfigClick.emit()"><tabler-icon [icon]="icSettings" [size]="16" /> {{ formConfigLabel() }}</li>
        }
        @if (hasMenuExtra()) {
          @if (hasMenu()) { <li nz-menu-divider></li> }
          <ng-content select="[wsMenuExtra]" />
        }
      </ul>
    </nz-dropdown-menu>

    <!-- Overlay Cấu hình cột: Column Manager (panel inline) + Inspector, dựng modal tự lo. -->
    @if (colOpen()) {
      <div class="hdw-cmg-mask" (click)="cmCancel()"></div>
      <div class="hdw-cmg-dialog" role="dialog" aria-modal="true" aria-labelledby="hdw-cmg-title" tabindex="-1"
        (keydown.escape)="cmCancel()">
        <div class="hdw-cmg-head">
          <span class="hdw-cmg-title" id="hdw-cmg-title">{{ columnConfigLabel() }}</span>
          <button type="button" class="hdw-cmg-x" [attr.aria-label]="closeLabel()" (click)="cmCancel()">
            <tabler-icon [icon]="icX" [size]="18" />
          </button>
        </div>
        <div class="hdw-cmg-body">
          <hrm-column-manager class="hdw-cmg-mgr" [(columns)]="cols" [(groups)]="columnGroups"
            (configColumn)="inspectorKey.set($event)" (configFormula)="openFormula($event)"
            (addComputed)="addComputed()" />
          <hrm-column-inspector class="hdw-cmg-insp" [column]="inspectorCol()" [groups]="columnGroups()"
            (columnChange)="onInspectorChange($event)" />
        </div>
        <div class="hdw-cmg-foot">
          <div class="hdw-cmg-foot-create">
            <hrm-button variant="dashed" (click)="cmRef()?.toggleCreate()">
              <tabler-icon [icon]="icPlus" [size]="15" /> {{ createGroupLabel() }}
            </hrm-button>
            <hrm-button variant="dashed" (click)="addComputed()">
              <tabler-icon [icon]="icFx" [size]="15" /> {{ addComputedLabel() }}
            </hrm-button>
          </div>
          <div class="hdw-cmg-foot-act">
            <hrm-button variant="default" (click)="cmCancel()">{{ cancelLabel() }}</hrm-button>
            <hrm-button variant="primary" [disabled]="!cmDirty()" (click)="cmSave()">{{ saveLabel() }}</hrm-button>
          </div>
        </div>
      </div>
    }

    <!-- Formula Builder (LIB) cho cột tính toán — mở từ nút mở rộng / thêm cột tính toán; ghi LIVE vào cols. -->
    <hrm-formula-builder [(open)]="formulaOpen" [columnName]="formulaColName()" [fields]="formulaFields()"
      [(formula)]="formulaVal" (aiRequest)="onAiFormula($event)" />

    <!-- Dialog Cấu hình sắp xếp đa cấp (tự bọc modal). -->
    <hrm-sort-config [(open)]="sortOpen" [columns]="sortColumns()" [(levels)]="sortLevels" />
  `,
  host: { class: 'hrm-data-workspace' },
  styles: [`
/* ViewEncapsulation.None ⇒ :host KHÔNG áp — style host qua class thật. */
.hrm-data-workspace { display: block; min-width: 0; height: 100%; }
/* Segmented đổi chế độ do WORKSPACE tự render ([headerActions]); ẩn thanh tab nội bộ của hrm-data-view
   để không TRÙNG 2 bộ chuyển chế độ (mọi consumer tự có, không phải thêm ::ng-deep). */
.hrm-data-workspace hrm-data-view .dv-bar { display: none; }

/* Cụm điều khiển cạnh tiêu đề — dồn phải, khoảng cách control chuẩn. */
.hdw-hdr { display: flex; align-items: center; justify-content: flex-end; gap: var(--space-2, 8px); }

/* Toolbar 2 trạng thái. */
.hdw-tbx { display: flex; align-items: center; gap: var(--space-2, 8px); min-width: 0; }
.hdw-search { width: 280px; max-width: 100%; }

/* Cụm chọn hàng loạt: nút bỏ chọn + đếm. */
.hdw-clear { display: grid; place-items: center; width: 28px; height: 28px; border: 0; background: transparent;
  border-radius: var(--radius-md, 8px); cursor: pointer; color: var(--text-sub); }
.hdw-clear:hover { background: var(--bg-surface-subtle); color: var(--text-strong); }
.hdw-count { font-size: var(--fs-13, 13px); color: var(--text-body); background: var(--primary-bg-subtle);
  padding: 4px 10px; border-radius: var(--radius-full, 999px); white-space: nowrap; }
.hdw-count b { color: var(--primary-base); }

/* Nút ⋮ More. */
.hdw-more { display: inline-flex; align-items: center; justify-content: center; width: 34px; height: 34px;
  border: 1px solid var(--border-sub); background: var(--bg-surface); border-radius: var(--radius-md, 8px);
  cursor: pointer; color: var(--text-sub); }
.hdw-more:hover { border-color: var(--primary-base); color: var(--text-strong); }

/* Nút TOGGLE "Nhóm dữ liệu" khi bật — SELECTED nền xanh đầy + chữ/icon trắng.
   ViewEncapsulation.None ⇒ selector .ant-btn (render bởi hrm-button) áp trực tiếp, KHÔNG cần ::ng-deep. */
.hdw-sel .ant-btn {
  box-shadow: inset 0 0 0 999px var(--primary-base) !important;
  border-color: var(--primary-base) !important;
  color: var(--text-on-primary) !important;
}
.hdw-sel .ant-btn:hover {
  box-shadow: inset 0 0 0 999px var(--primary-hover, var(--primary-base)) !important;
  border-color: var(--primary-hover, var(--primary-base)) !important;
  color: var(--text-on-primary) !important;
}
.hdw-sel .ant-btn tabler-icon { color: var(--icon-on-primary, var(--text-on-primary)) !important; }
.hdw-badge { display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 5px; margin-left: 2px;
  border-radius: var(--radius-full); background: var(--primary-base); color: var(--text-on-primary);
  font-size: var(--fs-11, 11px); font-weight: var(--font-semibold, 600); line-height: 1; }

/* Menu ⋮ — chỉ set màu icon (layout do bridge lo). */
.hdw-menu tabler-icon { color: var(--icon-secondary, var(--text-sub)); }

/* Overlay Cấu hình cột. */
.hdw-cmg-mask { position: fixed; inset: 0; background: var(--overlay); z-index: 1000; }
.hdw-cmg-dialog { position: fixed; z-index: 1001; top: 50%; left: 50%; transform: translate(-50%,-50%);
  width: min(920px, 94vw); height: min(640px, 88vh); display: flex; flex-direction: column;
  background: var(--bg-surface); border: 1px solid var(--border-sub); border-radius: var(--radius-xl, 12px);
  box-shadow: var(--shadow-regular-lg, 0 12px 32px rgba(0,0,0,.18)); overflow: hidden; }
.hdw-cmg-head { display: flex; align-items: center; justify-content: space-between; padding: 12px 16px;
  border-bottom: 1px solid var(--border-soft); }
.hdw-cmg-title { font-size: var(--fs-15, 15px); font-weight: var(--font-semibold, 600); color: var(--text-strong); }
.hdw-cmg-x { display: grid; place-items: center; width: 30px; height: 30px; border: 0; background: transparent;
  border-radius: var(--radius-md, 8px); cursor: pointer; color: var(--text-sub); }
.hdw-cmg-x:hover { background: var(--bg-surface-subtle); }
.hdw-cmg-body { flex: 1 1 auto; min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 320px); }
.hdw-cmg-mgr { min-width: 0; min-height: 0; height: 100%; display: flex; flex-direction: column;
  border-right: 1px solid var(--border-soft); padding: var(--space-2, 8px) 16px 16px; }
.hdw-cmg-insp { min-width: 0; min-height: 0; height: 100%; overflow: auto; }
/* Footer FULL modal: Tạo nhóm cột + Thêm cột tính toán bên trái · Huỷ/Lưu góc phải. */
.hdw-cmg-foot { flex: none; display: flex; align-items: center; gap: var(--space-3, 12px);
  padding: 10px 16px; border-top: 1px solid var(--border-soft); background: var(--bg-surface); }
.hdw-cmg-foot-create { display: flex; align-items: center; gap: var(--space-2, 8px); flex-wrap: wrap; }
.hdw-cmg-foot-act { display: flex; align-items: center; gap: var(--space-2, 8px); margin-inline-start: auto; }
@media (max-width: 640px) {
  .hdw-cmg-body { grid-template-columns: 1fr; grid-template-rows: minmax(0, 1fr) auto; }
  .hdw-cmg-mgr { border-right: 0; border-bottom: 1px solid var(--border-soft); padding: 12px; }
  /* Cap inspector bằng px cố định (tránh %-height cyclic với grid auto-track ⇒ inspector nuốt hết chỗ);
     column-list (mgr, 1fr) được ưu tiên, inspector cuộn trong 220px. */
  .hdw-cmg-insp { max-height: 220px; }
  .hdw-cmg-foot { flex-wrap: wrap; }
}
  `],
})
export class HrmDataWorkspace {
  // ── Tiêu đề ──
  readonly title = input('');
  readonly subtitle = input('');

  // ── Cột + dữ liệu ──
  /** Định nghĩa cột (HrmColumnDef). Consumer cấp; sửa trong Column Manager là VIEW-STATE nội bộ. */
  readonly columns = input<HrmColumnDef[]>([]);
  /** Map key → template ô (avatar/badge/nút…). Ngữ cảnh: $implicit=row, value=row[key]. */
  readonly cellTemplates = input<Record<string, TemplateRef<{ $implicit: Row; value: unknown }>>>({});
  /** Ô mặc định cho cột tính toán (computed=true) khi không có cellTemplates riêng. */
  readonly computedCell = input<TemplateRef<{ $implicit: Row; value: unknown }> | null>(null);
  readonly data = input<Row[]>([]);
  readonly rowKey = input('id');

  // ── Chế độ xem ──
  readonly modes = input<HrmDataViewMode[]>(['table']);
  readonly mode = model<HrmDataViewMode>('table');

  // ── Chọn hàng loạt ──
  readonly selectable = input(false);
  readonly selectedKeys = model<unknown[]>([]);
  readonly bulkUnit = input('mục');

  // ── Phân trang ──
  readonly total = input(0);
  readonly pageIndex = model(1);
  readonly pageSize = model(10);
  readonly showSizeChanger = input(false);
  readonly tableMinWidth = input('');
  readonly size = input<'small' | 'middle' | 'default'>('small');

  // ── Tìm kiếm + lọc nhanh ──
  readonly search = model('');
  readonly searchable = input(true);
  readonly searchPlaceholder = input('Tìm kiếm…');
  readonly quickFilters = input<HrmWorkspaceQuickFilter[]>([]);
  readonly quickFilterValues = model<Record<string, string[]>>({});

  // ── Cờ bật tính năng ──
  readonly groupable = input(false);
  readonly exportable = input(false);
  readonly importable = input(false);
  readonly printable = input(false);
  readonly columnConfig = input(false);
  readonly sortConfig = input(false);
  readonly formConfig = input(false);

  // ── Cấu hình bảng (two-way, forward xuống data-view) ──
  readonly sortLevels = model<HrmGridSort[]>([]);
  readonly hiddenKeys = model<string[]>([]);
  readonly rowGroups = model<HrmRowGroupLevel[]>([]);
  readonly showGroupPanel = model(false);
  readonly columnGroups = model<HrmColumnGroup[]>([]);
  readonly groupLabelFormatter = input<((key: string, value: unknown) => string) | null>(null);

  // ── Nhãn (i18n) ──
  readonly exportLabel = input('Xuất dữ liệu');
  readonly groupLabel = input('Nhóm dữ liệu');
  readonly importLabel = input('Nhập dữ liệu');
  readonly printLabel = input('In danh sách');
  readonly columnConfigLabel = input('Cấu hình bảng');
  readonly sortConfigLabel = input('Cấu hình sắp xếp');
  readonly formConfigLabel = input('Cấu hình biểu mẫu');
  readonly moreLabel = input('Thêm thao tác');
  readonly closeLabel = input('Đóng');
  readonly saveLabel = input('Lưu');
  readonly cancelLabel = input('Huỷ');
  readonly unsavedLabel = input('Thay đổi chưa lưu');
  readonly createGroupLabel = input('Tạo nhóm cột');
  readonly addComputedLabel = input('Thêm cột tính toán');
  readonly selectedLabel = input('Đã chọn');
  readonly clearSelectionLabel = input('Bỏ chọn');

  // ── Kanban / Gantt (forward xuống hrm-data-view) ──
  readonly groupBy = input('status');
  readonly boardGroups = input<any[]>([]);
  readonly cardTemplate = input<TemplateRef<{ $implicit: Row }> | null>(null);
  readonly boardCardTemplate = input<TemplateRef<{ $implicit: Row }> | null>(null);
  readonly boardAddLabel = input('');
  readonly startField = input('start');
  readonly endField = input('end');
  readonly progressField = input('');
  readonly ganttLabelField = input('name');
  readonly ganttHeader = input('');
  readonly ganttDateHeader = input('');
  readonly ganttLabelTemplate = input<TemplateRef<{ $implicit: Row }> | null>(null);
  readonly ganttBarTone = input<((row: Row) => string) | null>(null);

  // ── Outputs ──
  readonly exportClick = output<void>();
  readonly importClick = output<void>();
  readonly printClick = output<void>();
  readonly formConfigClick = output<void>();
  readonly rowClick = output<Row>();
  readonly boardAdd = output<unknown>();
  readonly groupChange = output<unknown>();
  /** Cột được đánh dấu có mục ⋮ domain (consumer bật khi có [wsMenuExtra]) → hiện divider + slot. */
  readonly hasMenuExtra = input(false);
  /** Cột được đánh dấu có mục ⋮ domain ở ĐỈNH menu (trên Nhập/In) → hiện [wsMenuTop] + divider. */
  readonly hasMenuTop = input(false);

  // ── Icon ──
  protected readonly icMore = IconDotsVertical;
  protected readonly icDownload = IconDownload;
  protected readonly icGroup = IconLayoutList;
  protected readonly icImport = IconFileImport;
  protected readonly icPrint = IconPrinter;
  protected readonly icColumns = IconColumns3;
  protected readonly icSort = IconArrowsSort;
  protected readonly icSettings = IconSettings;
  protected readonly icX = IconX;
  protected readonly icPlus = IconPlus;
  protected readonly icFx = IconMathFunction;

  /** Tham chiếu Column Manager (trong overlay) — footer modal gọi toggleCreate() để mở popover tạo nhóm. */
  protected readonly cmRef = viewChild(HrmColumnManager);

  // ── State nội bộ ──
  /** Bản sao cột (view-state) — Column Manager/Inspector sửa vào đây; seed từ columns() input. */
  protected readonly cols = signal<HrmColumnDef[]>([]);
  /** Cờ mở overlay/dialog cấu hình. */
  protected readonly colOpen = signal(false);
  protected readonly sortOpen = signal(false);
  /** Khoá cột đang mở Inspector. */
  protected readonly inspectorKey = signal<string | null>(null);
  /** Cờ mở modal Formula Builder + khoá cột đang soạn công thức. */
  protected readonly formulaOpen = signal(false);
  protected readonly formulaKey = signal<string | null>(null);

  /** Đã seed cols từ columns() lần đầu chưa (tránh ghi đè chỉnh sửa Column Manager khi columns() re-emit). */
  private colsSeeded = false;
  /** Cột tính toán VỪA tạo qua "Thêm cột" (chưa lưu công thức) — để tự dọn nếu user bỏ dở (Huỷ/×). */
  private formulaWasNew = false;
  private fbWasOpen = false;

  /** Ảnh chụp cols+groups (JSON) khi MỞ dialog — để so dirty + revert khi Huỷ. */
  private readonly cmSnapshot = signal<{ cols: string; groups: string } | null>(null);
  private cmWasOpen = false;
  /** Có thay đổi cấu hình chưa lưu so với lúc mở dialog. */
  protected readonly cmDirty = computed(() => {
    const s = this.cmSnapshot();
    if (!s) return false;
    return JSON.stringify(this.cols()) !== s.cols || JSON.stringify(this.columnGroups()) !== s.groups;
  });

  constructor() {
    // Seed MỘT LẦN input columns() → cols nội bộ (lần đầu có cột); sau đó Column Manager tự quản view-state.
    effect(() => {
      const c = this.columns();
      if (this.colsSeeded || !c.length) return;
      this.cols.set(c.map((x) => ({ ...x })));
      this.colsSeeded = true;
    });
    // Đồng bộ MỘT CHIỀU cột ẩn (visible=false) → hiddenKeys → data-view/grid ẩn cột.
    effect(() => {
      const hidden = this.cols().filter((c) => c.visible === false).map((c) => c.key);
      this.hiddenKeys.set(hidden);
    });
    // Đóng Formula Builder mà cột VỪA tạo còn RỖNG công thức (Huỷ/×) ⇒ tự xoá cột rác.
    effect(() => {
      const o = this.formulaOpen();
      if (!o && this.fbWasOpen && this.formulaWasNew) {
        const key = this.formulaKey();
        const col = this.cols().find((c) => c.key === key);
        if (col && !(col.formula ?? '').trim()) {
          this.cols.update((cs) => cs.filter((c) => c.key !== key));
        }
        this.formulaWasNew = false;
      }
      this.fbWasOpen = o;
    });
    // Chụp snapshot cols+groups khi MỞ dialog cấu hình (chỉ track colOpen; đọc cols/groups untracked).
    effect(() => {
      const open = this.colOpen();
      if (open && !this.cmWasOpen) {
        this.cmSnapshot.set({
          cols: JSON.stringify(untracked(() => this.cols())),
          groups: JSON.stringify(untracked(() => this.columnGroups())),
        });
      }
      this.cmWasOpen = open;
    });
  }

  /** Huỷ: khôi phục snapshot (revert mọi thay đổi cấu hình) rồi đóng. */
  protected cmCancel(): void {
    const s = this.cmSnapshot();
    if (s) {
      this.cols.set(JSON.parse(s.cols) as HrmColumnDef[]);
      this.columnGroups.set(JSON.parse(s.groups) as HrmColumnGroup[]);
    }
    this.inspectorKey.set(null);
    this.colOpen.set(false);
  }
  /** Lưu: giữ nguyên thay đổi (đã áp live) rồi đóng. */
  protected cmSave(): void {
    this.inspectorKey.set(null);
    this.colOpen.set(false);
  }

  /** Nhãn mặc định (VN) cho segmented đổi chế độ — theo HrmDataViewMode. */
  private readonly modeLabels: Record<HrmDataViewMode, string> = {
    table: 'Bảng', card: 'Thẻ', kanban: 'Kanban', gantt: 'Gantt',
  };
  /** Options segmented đổi chế độ — suy từ modes(). */
  protected readonly segmentOptions = computed(() =>
    this.modes().map((m) => ({ label: this.modeLabels[m], value: m })));

  /** Cột đang mở Inspector (đầy đủ HrmColumnDef) — null ⇒ Inspector hiện empty-state. */
  protected readonly inspectorCol = computed<HrmColumnDef | null>(() =>
    this.cols().find((c) => c.key === this.inspectorKey()) ?? null);

  /** Tên cột tính toán đang soạn công thức (phụ đề modal Formula Builder). */
  protected readonly formulaColName = computed<string>(() =>
    this.cols().find((c) => c.key === this.formulaKey())?.title ?? '');

  /** Trường (cột dữ liệu, KHÔNG gồm cột tính toán) cho vùng "Trường" của Formula Builder → bấm chèn token. */
  protected readonly formulaFields = computed(() =>
    this.cols().filter((c) => !c.computed).map((c) => ({ key: c.key, title: c.title, type: c.type })));

  /** Accessor 2 chiều cho [(formula)]: đọc/ghi col.formula LIVE vào cols (đồng bộ ô inline của Column Manager). */
  protected get formulaVal(): string {
    return this.cols().find((c) => c.key === this.formulaKey())?.formula ?? '';
  }
  protected set formulaVal(v: string) {
    this.cols.update((cs) => cs.map((c) => (c.key === this.formulaKey() ? { ...c, formula: v } : c)));
  }

  /** Cột chọn được cho dialog Sắp xếp — bỏ cột ẩn + cột tính toán (không sort được). */
  protected readonly sortColumns = computed<HrmSortColumn[]>(() =>
    this.cols().filter((c) => c.visible !== false && !c.computed && c.sortable !== false && c.key !== 'act').map((c) => ({ key: c.key, title: c.title })));

  /** Còn mục nào để hiện menu ⋮ không. */
  protected readonly hasMenu = computed(() =>
    this.importable() || this.printable() || this.columnConfig() || this.sortConfig() || this.formConfig());

  /** Cột thực cho <hrm-data-view> — suy từ cols nội bộ: ẩn cột, căn lề, ghim, cell theo key. */
  protected readonly gridCols = computed<HrmGridColumn[]>(() => {
    const cellByKey = this.cellTemplates();
    const computedTpl = this.computedCell();
    return this.cols().filter((c) => c.visible !== false).map((c) => ({
      key: c.key,
      title: c.title,
      width: c.width || undefined,
      align: (c.align && c.align !== 'auto') ? c.align : hrmAutoAlign(c.type),
      fixed: c.pin === 'left' ? 'left' : c.pin === 'right' ? 'right' : undefined,
      sortable: c.sortable !== false && c.key !== 'act' && !c.computed,
      computed: c.computed,
      groupId: c.groupId ?? undefined,
      cell: cellByKey[c.key] ?? (c.computed ? (computedTpl ?? undefined) : undefined),
    }));
  });

  /** Giá trị lọc nhanh 1 key (mảng rỗng nếu chưa chọn). */
  protected qfValue(key: string): string[] { return this.quickFilterValues()[key] ?? []; }
  /** Ghi giá trị lọc nhanh 1 key vào quickFilterValues (two-way). */
  protected setQf(key: string, value: string[]): void {
    this.quickFilterValues.update((o) => ({ ...o, [key]: value }));
  }

  /** Mở modal Formula Builder cho 1 cột tính toán (nút mở rộng / tag Công thức ở card cột tính toán). */
  protected openFormula(key: string): void {
    this.formulaWasNew = false; // mở cột CÓ SẴN (từ nút mở rộng) → không tự xoá khi đóng
    this.formulaKey.set(key);
    this.formulaOpen.set(true);
  }

  /** Column Manager: "Thêm cột tính toán" → tạo cột computed rỗng rồi mở Formula Builder cho cột đó. */
  protected addComputed(): void {
    // Key DUY NHẤT — tăng dần tới khi không trùng (tránh trùng sau add/xoá/add → 2 cột cùng key).
    let n = this.cols().length + 1;
    let id = 'calc_' + n;
    while (this.cols().some((c) => c.key === id)) { n++; id = 'calc_' + n; }
    this.cols.update((cs) => [...cs, { key: id, title: 'Cột tính toán', type: 'number', computed: true, visible: true, formula: '' }]);
    this.openFormula(id);
    this.formulaWasNew = true; // vừa tạo → nếu bỏ dở (Huỷ/×) thì effect tự xoá cột rỗng
  }

  /** AI: demo → sinh 1 công thức mẫu ghi vào cột (consumer thật sẽ gọi LLM rồi set formulaVal). */
  protected onAiFormula(prompt: string): void {
    void prompt;
    this.formulaVal = 'NOI([Họ tên]; " · "; [Email])';
  }

  /** Inspector sửa 1 cột (two-way) → ghi lại vào cols theo key. */
  protected onInspectorChange(col: HrmColumnDef): void {
    this.cols.update((cs) => cs.map((c) => (c.key === col.key ? { ...col } : c)));
  }
}
