import { ChangeDetectionStrategy, Component, ElementRef, ViewEncapsulation, computed, effect, input, model, output, signal, viewChild } from '@angular/core';
import { TablerIconComponent, IconSearch, IconX, IconSparkles, IconChevronDown, IconChevronRight, IconCheck, IconAlertTriangle } from '@tabler/icons-angular';

/**
 * hrm-formula-builder — REDESIGN "Cấu hình công thức" (Formula Builder) cho cột tính toán.
 *
 *  MENTAL MODEL: một workspace 3 VÙNG, editor là trọng tâm, empty-state NHẸ (không khối cảnh báo đỏ to):
 *   - VÙNG TRÁI "TRƯỜNG": tìm + chọn cột dùng được → chèn token [Tên] vào công thức tại con trỏ.
 *   - VÙNG GIỮA "CÔNG THỨC": textarea mono (rộng nhất) + trạng thái validate nhẹ + AI inline (mô tả → sinh).
 *   - VÙNG PHẢI "TOÁN TỬ & HÀM": tìm + nhóm gập/mở; chọn 1 mục = chèn tại con trỏ (hàm chèn TÊN() và đặt con trỏ giữa ngoặc).
 *
 *  Consumer tự tính previewValue (kết quả mẫu) và tự gọi AI (bắt aiRequest → set [(formula)]).
 *  Component KHÔNG tự chạy công thức — chỉ soạn thảo + validate cân bằng ngoặc cơ bản.
 *
 *  <hrm-formula-builder
 *     [(open)]="fxOpen" [columnName]="col.title" [fields]="usableFields"
 *     [(formula)]="col.formula" [previewValue]="fxSample"
 *     (apply)="onApplyFormula($event)" (aiRequest)="onAskAi($event)" />
 */

/** 1 mục trong catalog phải (toán tử hoặc hàm). */
export interface HrmFormulaItem {
  /** Nhãn hiển thị (toán tử: ký tự; hàm: TÊN). */
  label: string;
  /** Mô tả ngắn 1 dòng. */
  desc: string;
  /** Chuỗi chèn thực tế — CHỈ dùng cho toán tử (hàm tự suy TÊN() ). */
  insert?: string;
}

/** 1 nhóm trong vùng phải; variant quyết định cách render + cách chèn. */
export interface HrmFormulaGroup {
  id: string;
  title: string;
  /** 'ops' = lưới nút ký tự · 'fns' = danh sách hàm TÊN + mô tả. */
  variant: 'ops' | 'fns';
  items: HrmFormulaItem[];
}

