/** Trạng thái validate của công thức (kind quyết định dòng hiển thị dưới editor). */
interface HrmFormulaStatus { kind: 'empty' | 'ok' | 'error'; msg: string; }

/** Kiểm tra cân bằng ngoặc () và [ ] — chỉ báo ĐỎ khi thực sự lệch. */
function hrmValidateFormula(raw: string): HrmFormulaStatus {
  const f = raw.trim();
  if (!f) return { kind: 'empty', msg: '' };
  let paren = 0, brack = 0;
  for (const ch of raw) {
    if (ch === '(') paren++;
    else if (ch === ')') { paren--; if (paren < 0) return { kind: 'error', msg: 'Thừa dấu ) — thiếu dấu ( mở ngoặc.' }; }
    else if (ch === '[') brack++;
    else if (ch === ']') { brack--; if (brack < 0) return { kind: 'error', msg: 'Thừa dấu ] — thiếu dấu [ mở tên trường.' }; }
  }
  if (paren > 0) return { kind: 'error', msg: 'Thiếu dấu ) đóng ngoặc.' };
  if (brack > 0) return { kind: 'error', msg: 'Thiếu dấu ] đóng tên trường.' };
  return { kind: 'ok', msg: '' };
}

