  readonly editorPlaceholder = input('Nhập công thức hoặc chọn trường, hàm bên cạnh…');
  readonly hintEmpty = input('Bắt đầu bằng cách chọn một trường hoặc nhập công thức.');
  readonly validText = input('Ngoặc cân đối');
  readonly sampleLabel = input('Kết quả mẫu');
  readonly aiToggleLabel = input('Tạo công thức bằng mô tả');
  readonly aiPlaceholder = input('Mô tả kết quả bạn muốn');
  readonly aiGenerateLabel = input('Tạo công thức');
  readonly funcsTitle = input('Toán tử & Hàm');
  readonly funcsSearchPlaceholder = input('Tìm hàm…');
  readonly funcsEmpty = input('Không có hàm phù hợp.');
  readonly cancelLabel = input('Huỷ');
