/**
 * @file Contract DÙNG CHUNG cho bộ "Chế độ xem dữ liệu" (redesign Enterprise SaaS / No-code Data Platform).
 *  Mọi component (ColumnManager · ColumnInspector · RowGrouping · FormulaBuilder · ViewManager) bám types này
 *  để ghép được với nhau. KHÔNG hard-code UI cho 1 màn — tái dùng cho CRM/HRM/Payroll/Finance/Insurance/Report.
 *
 *  MENTAL MODEL (phải giữ đúng):
 *   - NHÓM CỘT (HrmColumnGroup): gom cột dưới 1 tiêu đề chung trên header — tổ chức theo CHIỀU NGANG.
 *     Thuộc phạm vi Cấu hình cột (ColumnManager).
 *   - NHÓM DỮ LIỆU (HrmRowGroupLevel): gom HÀNG theo giá trị cột — tổ chức theo CHIỀU DỌC.
 *     Là chức năng ĐỘC LẬP trên toolbar (RowGrouping kiểu Kendo). KHÔNG trộn vào Cấu hình cột.
 */

/** Kiểu dữ liệu cột — quyết định format mặc định + căn lề 'auto'. */
export type HrmDataType =
  | 'text' | 'number' | 'money' | 'date' | 'percent' | 'status' | 'user' | 'boolean';

export type HrmColAlign = 'auto' | 'left' | 'center' | 'right';
export type HrmColContent = 'truncate' | 'wrap';
export type HrmColPin = 'none' | 'left' | 'right';
/** 'auto' | số px dạng chuỗi ('160px') | '' = tự động. */
export type HrmColWidth = string;

/** 1 cột (thường HOẶC cột tính toán). */
export interface HrmColumnDef {
  key: string;
  title: string;
  /** Kiểu dữ liệu — bỏ trống ⇒ coi như 'text'. Quyết định bộ Định dạng + align 'auto'. */
  type?: HrmDataType;
  /** Hiển thị trên bảng. Mặc định true. */
  visible?: boolean;
  /** '' | 'auto' | 'NNNpx'. */
  width?: HrmColWidth;
  /** 'auto' ⇒ suy theo type (text→trái, number/money/percent→phải, status/user→trái). */
  align?: HrmColAlign;
  content?: HrmColContent;
  /** Mã format theo type — xem HRM_FORMAT_OPTIONS. Bỏ trống = 'auto'/'default'. */
  format?: string;
  pin?: HrmColPin;
  /** Thuộc nhóm cột nào (id của HrmColumnGroup); null/undefined = cột phẳng không thuộc nhóm. */
  groupId?: string | null;
  /** Cột tính toán (giá trị suy từ cột khác cùng dòng; chỉ để xem/xuất, không ghi bản ghi). */
  computed?: boolean;
  /** Công thức (khi computed). */
  formula?: string;
  /** Cho phép ẩn. Mặc định true; false = cột bắt buộc luôn hiện. */
  hideable?: boolean;
  /** Cho phép sắp xếp. Mặc định true; false = cột tiện ích (thao tác…) không sort/không vào Cấu hình sắp xếp. */
  sortable?: boolean;
}

/** Nhóm cột (header chung theo chiều ngang). Thứ tự cột trong nhóm quản qua thứ tự HrmColumnDef + groupId. */
export interface HrmColumnGroup {
  id: string;
  title: string;
}

/** 1 cấp NHÓM DỮ LIỆU (chiều dọc) — nhiều cấp = nhóm lồng nhau. */
export interface HrmRowGroupLevel {
  key: string;
  /** Hướng sort của cấp nhóm. */
  dir: 'asc' | 'desc';
}

/** 1 cấp SẮP XẾP (đồng bộ với HrmGridSort của hrm-grid). */
export interface HrmSortLevel {
  key: string;
  dir: 'asc' | 'desc';
}

/** Chế độ xem đã lưu — TOÀN BỘ trạng thái bảng (thay khái niệm "Mẫu cột"). */
export interface HrmViewConfig {
  id: string;
  name: string;
  columns: HrmColumnDef[];
  groups: HrmColumnGroup[];
  sort: HrmSortLevel[];
  rowGroups: HrmRowGroupLevel[];
  density?: 'compact' | 'balanced' | 'spacious';
}

/** 1 lựa chọn định dạng cho Inspector (value = mã lưu vào HrmColumnDef.format). */
export interface HrmFormatOption {
  value: string;
  label: string;
  /** Mẫu minh hoạ (VD "1.234,00"). */
  sample?: string;
}

