/** Căn lề mặc định suy theo kiểu dữ liệu khi align='auto'. */
export function hrmAutoAlign(type: HrmDataType | undefined): 'left' | 'right' | 'center' {
  switch (type) {
    case 'number': case 'money': case 'percent': return 'right';
    case 'boolean': return 'center';
    default: return 'left';
  }
}

/** Icon gợi ý (tên Tabler, KHÔNG kèm 'Icon') theo kiểu dữ liệu — component tự map sang IconXxx. */
export function hrmTypeIcon(type: HrmDataType | undefined): string {
  switch (type) {
    case 'number': return 'Hash';
    case 'money': return 'Coin';
    case 'percent': return 'Percentage';
    case 'date': return 'Calendar';
    case 'status': return 'CircleDot';
    case 'user': return 'User';
    case 'boolean': return 'ToggleLeft';
    default: return 'Letter-case';
  }
}
