/**
 * hrm-column-inspector — panel cấu hình CHI TIẾT 1 cột (Tầng 2 của bộ "Cấu hình cột").
 *  Hiện bên phải khi bấm ⚙ trên 1 cột ở ColumnManager. Bám contract hrm-data-config.types.
 *
 *  ĐẶC ĐIỂM CỐT LÕI: bộ Định dạng ĐỔI THEO KIỂU DỮ LIỆU — options lấy từ
 *  HRM_FORMAT_OPTIONS[column.type] (text/number/money/date/percent/status/user/boolean),
 *  KHÔNG dùng chung 1 bộ cho mọi cột. Căn lề 'Tự động' hiển thị chú thích suy theo kiểu (hrmAutoAlign).
 *
 *  Sửa two-way trên column(): mỗi thao tác gọi column.set({ ...column(), field: val }).
 *  column() === null ⇒ empty state ("Chọn một cột để xem cấu hình.").
 *
 *  Bố cục: [tên cột đậm + "Cột <loại>" + bút chì đổi tên inline]
 *          nhóm HIỂN THỊ (Độ rộng · Căn lề · Nội dung · Định dạng)
 *          nhóm VỊ TRÍ (Nhóm cột · Ghim).
 *
 *  <hrm-column-inspector [(column)]="editingCol" [groups]="colGroups()" />
 */
import { ChangeDetectionStrategy, Component, ViewEncapsulation, computed, input, model, signal } from '@angular/core';
import { TablerIconComponent, IconPencil, IconChevronDown } from '@tabler/icons-angular';
import {
  HrmColumnDef, HrmColumnGroup, HrmDataType, HrmColAlign, HrmColContent, HrmColPin,
  HRM_FORMAT_OPTIONS, hrmAutoAlign,
} from './hrm-data-config.types';

@Component({
  selector: 'hrm-column-inspector',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  imports: [TablerIconComponent],
  template: `
    @if (!column()) {
      <div class="ci-empty">{{ emptyLabel() }}</div>
    } @else {
      <div class="ci">
        <!-- Đầu panel: tên cột + kiểu + nút đổi tên inline -->
        <header class="ci-head">
          <div class="ci-head-main">
            @if (editingName()) {
              <input class="ci-name-inp" type="text" [value]="nameDraft()" autofocus
                [attr.aria-label]="renameLabel()"
                (input)="nameDraft.set($any($event.target).value)"
                (keydown.enter)="commitName()" (keydown.escape)="cancelName()" (blur)="commitName()" />
            } @else {
              <div class="ci-name" [title]="column()!.title">{{ column()!.title }}</div>
            }
            <div class="ci-type">{{ columnWordLabel() }} {{ typeWord() }}</div>
          </div>
          @if (!editingName()) {
            <button type="button" class="ci-pen" [attr.aria-label]="renameLabel()" (click)="startName()">
              <tabler-icon [icon]="icPencil" [size]="16" />
            </button>
          }
        </header>

        <!-- Nhóm HIỂN THỊ -->
        <div class="ci-sec">{{ displaySectionLabel() }}</div>

        <div class="ci-row">
          <span class="ci-lb">{{ widthLabel() }}</span>
          <div class="ci-sel ci-ctl">
            <select [value]="widthValue()" [attr.aria-label]="widthLabel()"
              (change)="patch({ width: $any($event.target).value })">
              @for (w of widthOptions(); track w.value) {
                <option [value]="w.value" [selected]="w.value === widthValue()">{{ w.label }}</option>
              }
            </select>
            <tabler-icon class="ci-sel-ic" [icon]="icChevron" [size]="16" />
          </div>
        </div>

        <div class="ci-row">
          <span class="ci-lb">{{ alignLabel() }}</span>
          <div class="ci-ctl ci-ctl-col">
            <div class="ci-seg" role="group" [attr.aria-label]="alignLabel()">
              <button type="button" [class.on]="align() === 'auto'" (click)="patch({ align: 'auto' })">{{ alignAutoLabel() }}</button>
              <button type="button" [class.on]="align() === 'left'" (click)="patch({ align: 'left' })">{{ alignLeftLabel() }}</button>
              <button type="button" [class.on]="align() === 'center'" (click)="patch({ align: 'center' })">{{ alignCenterLabel() }}</button>
              <button type="button" [class.on]="align() === 'right'" (click)="patch({ align: 'right' })">{{ alignRightLabel() }}</button>
            </div>
            @if (align() === 'auto') {
              <span class="ci-hint">({{ autoByTypeLabel() }}: {{ autoAlignWord() }})</span>
            }
          </div>
        </div>

        <div class="ci-row">
          <span class="ci-lb">{{ contentLabel() }}</span>
          <div class="ci-seg ci-ctl" role="group" [attr.aria-label]="contentLabel()">
            <button type="button" [class.on]="content() === 'truncate'" (click)="patch({ content: 'truncate' })">{{ contentTruncateLabel() }}</button>
            <button type="button" [class.on]="content() === 'wrap'" (click)="patch({ content: 'wrap' })">{{ contentWrapLabel() }}</button>
          </div>
        </div>

        <div class="ci-row">
          <span class="ci-lb">{{ formatLabel() }}</span>
          <!-- Dropdown tuỳ biến để hiện label + mẫu (sample) mờ bên phải mỗi option -->
          <div class="ci-dd ci-ctl" [class.open]="fmtOpen()">
            <button type="button" class="ci-dd-tg" [attr.aria-expanded]="fmtOpen()" (click)="fmtOpen.set(!fmtOpen())">
              <span class="ci-dd-lb">{{ currentFormat().label }}</span>
              @if (currentFormat().sample) { <span class="ci-dd-sample">{{ currentFormat().sample }}</span> }
              <tabler-icon class="ci-dd-ic" [icon]="icChevron" [size]="16" />
            </button>
            @if (fmtOpen()) {
              <button type="button" class="ci-scrim" tabindex="-1" aria-hidden="true" (click)="fmtOpen.set(false)"></button>
              <ul class="ci-pop" role="listbox">
                @for (o of formatOptions(); track o.value) {
                  <li role="option" [attr.aria-selected]="o.value === currentFormat().value"
                    [class.sel]="o.value === currentFormat().value" (click)="setFormat(o.value)">
                    <span class="ci-opt-lb">{{ o.label }}</span>
                    @if (o.sample) { <span class="ci-opt-sample">{{ o.sample }}</span> }
                  </li>
                }
              </ul>
            }
          </div>
        </div>

        <!-- Nhóm VỊ TRÍ -->
        <div class="ci-sec">{{ positionSectionLabel() }}</div>

        <div class="ci-row">
          <span class="ci-lb">{{ groupLabel() }}</span>
          <div class="ci-sel ci-ctl">
            <select [value]="groupValue()" [attr.aria-label]="groupLabel()"
              (change)="patch({ groupId: $any($event.target).value || null })">
              <option value="" [selected]="groupValue() === ''">{{ noGroupLabel() }}</option>
              @for (g of groups(); track g.id) {
                <option [value]="g.id" [selected]="g.id === groupValue()">{{ g.title }}</option>
              }
            </select>
            <tabler-icon class="ci-sel-ic" [icon]="icChevron" [size]="16" />
          </div>
        </div>

        <div class="ci-row">
          <span class="ci-lb">{{ pinLabel() }}</span>
          <div class="ci-seg ci-ctl" role="group" [attr.aria-label]="pinLabel()">
            <button type="button" [class.on]="pin() === 'none'" (click)="patch({ pin: 'none' })">{{ pinNoneLabel() }}</button>
            <button type="button" [class.on]="pin() === 'left'" (click)="patch({ pin: 'left' })">{{ pinLeftLabel() }}</button>
            <button type="button" [class.on]="pin() === 'right'" (click)="patch({ pin: 'right' })">{{ pinRightLabel() }}</button>
          </div>
        </div>
      </div>
    }
  `,
  host: { class: 'hrm-column-inspector' },
  styles: [`
.hrm-column-inspector { display: block; background: var(--bg-surface); font-family: var(--font-sans); }

.ci-empty { padding: var(--space-6, 24px) var(--space-4, 16px); text-align: center;
  font-size: var(--fs-13, 13px); color: var(--text-soft); }

.ci { display: flex; flex-direction: column; padding: var(--space-4, 16px); }

.ci-head { display: flex; align-items: flex-start; gap: var(--space-2, 8px); padding-bottom: var(--space-3, 12px);
  border-bottom: 1px solid var(--border-soft); }
.ci-head-main { flex: 1; min-width: 0; }
.ci-name { font-size: var(--fs-15, 15px); font-weight: var(--font-semibold, 600); color: var(--text-strong);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ci-type { margin-top: 2px; font-size: var(--fs-12, 12px); color: var(--text-sub); }
.ci-name-inp { width: 100%; height: 30px; padding: 0 8px; border: 1px solid var(--primary-base);
  border-radius: var(--radius-sm, 6px); background: var(--bg-surface); color: var(--text-strong);
  font: inherit; font-size: var(--fs-15, 15px); font-weight: var(--font-semibold, 600); }
.ci-name-inp:focus-visible { outline: 2px solid var(--primary-focus-ring, var(--primary-base)); outline-offset: 1px; }
.ci-pen { flex: none; display: grid; place-items: center; width: 28px; height: 28px; border: 0; background: transparent;
  border-radius: var(--radius-md, 8px); color: var(--text-soft); cursor: pointer; }
.ci-pen:hover { background: var(--bg-surface-subtle); color: var(--text-strong); }

.ci-sec { margin: var(--space-4, 16px) 0 var(--space-2, 8px); font-size: var(--fs-11, 11px);
  font-weight: var(--font-semibold, 600); letter-spacing: .04em; text-transform: uppercase; color: var(--text-soft); }

.ci-row { display: flex; align-items: flex-start; justify-content: space-between; gap: var(--space-3, 12px);
  min-height: 36px; padding: var(--space-1, 4px) 0; }
.ci-lb { flex: none; padding-top: 8px; font-size: var(--fs-13, 13px); color: var(--text-sub); }
.ci-ctl { flex: 0 0 auto; }
.ci-ctl-col { display: flex; flex-direction: column; align-items: flex-end; gap: var(--space-1, 4px); }
.ci-hint { font-size: var(--fs-11, 11px); color: var(--text-soft); }

/* Select native + chevron overlay */
.ci-sel { position: relative; width: 176px; }
.ci-sel select { width: 100%; height: 34px; padding: 0 30px 0 10px; border: 1px solid var(--border-sub);
  border-radius: var(--radius-md, 8px); background: var(--bg-surface); color: var(--text-body); font: inherit;
  font-size: var(--fs-13, 13px); cursor: pointer; appearance: none; -webkit-appearance: none; }
.ci-sel select:hover { border-color: var(--primary-border, var(--border-sub)); }
.ci-sel select:focus-visible { outline: 2px solid var(--primary-focus-ring, var(--primary-base)); outline-offset: 1px; border-color: var(--primary-base); }
.ci-sel-ic { position: absolute; inset-inline-end: 8px; top: 50%; transform: translateY(-50%); color: var(--text-soft); pointer-events: none; }

/* Segmented (nút tự dựng) */
.ci-seg { display: inline-flex; border: 1px solid var(--border-sub); border-radius: var(--radius-md, 8px); overflow: hidden; }
.ci-seg button { display: inline-flex; align-items: center; height: 32px; padding: 0 10px; border: 0; background: transparent;
  color: var(--text-sub); font: inherit; font-size: var(--fs-13, 13px); cursor: pointer;
  transition: background var(--duration-fast, .15s) var(--ease-out, ease), color var(--duration-fast, .15s) var(--ease-out, ease); }
.ci-seg button + button { border-inline-start: 1px solid var(--border-sub); }
.ci-seg button:hover { color: var(--text-strong); }
.ci-seg button.on { background: var(--primary-bg-subtle); color: var(--primary-base); font-weight: var(--font-medium, 500); }
.ci-seg button:focus-visible { outline: 2px solid var(--primary-focus-ring, var(--primary-base)); outline-offset: -2px; }

/* Dropdown Định dạng: trigger giống select nhưng list hiện label + sample mờ */
.ci-dd { position: relative; width: 200px; }
.ci-dd-tg { display: flex; align-items: center; gap: var(--space-2, 8px); width: 100%; height: 34px; padding: 0 8px 0 10px;
  border: 1px solid var(--border-sub); border-radius: var(--radius-md, 8px); background: var(--bg-surface);
  color: var(--text-body); font: inherit; font-size: var(--fs-13, 13px); cursor: pointer; text-align: start; }
.ci-dd-tg:hover { border-color: var(--primary-border, var(--border-sub)); }
.ci-dd.open .ci-dd-tg, .ci-dd-tg:focus-visible { outline: 2px solid var(--primary-focus-ring, var(--primary-base)); outline-offset: 1px; border-color: var(--primary-base); }
.ci-dd-lb { flex: none; color: var(--text-body); }
.ci-dd-sample { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; text-align: end; color: var(--text-soft); font-size: var(--fs-12, 12px); }
.ci-dd-ic { flex: none; margin-inline-start: auto; color: var(--text-soft); }
.ci-dd.open .ci-dd-ic { color: var(--primary-base); }

.ci-scrim { position: fixed; inset: 0; z-index: 40; border: 0; background: transparent; cursor: default; }
.ci-pop { position: absolute; z-index: 41; top: calc(100% + 4px); inset-inline-end: 0; min-width: 100%; margin: 0; padding: var(--space-1, 4px);
  list-style: none; background: var(--bg-surface); border: 1px solid var(--border-sub); border-radius: var(--radius-md, 8px);
  box-shadow: var(--shadow-regular-md, 0 6px 20px rgba(0,0,0,.12)); max-height: 260px; overflow-y: auto; }
.ci-pop li { display: flex; align-items: center; gap: var(--space-3, 12px); min-height: 32px; padding: 0 10px;
  border-radius: var(--radius-sm, 6px); font-size: var(--fs-13, 13px); color: var(--text-body); cursor: pointer; }
.ci-pop li:hover { background: var(--bg-surface-subtle); }
.ci-pop li.sel { background: var(--primary-bg-subtle); color: var(--primary-base); font-weight: var(--font-medium, 500); }
.ci-opt-lb { flex: none; }
.ci-opt-sample { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  text-align: end; color: var(--text-soft); font-size: var(--fs-12, 12px); }
.ci-pop li.sel .ci-opt-sample { color: var(--primary-base); opacity: .7; }
  `],
})
export class HrmColumnInspector {
  /** Cột đang sửa (two-way). null ⇒ ẩn/empty state. */
  readonly column = model<HrmColumnDef | null>(null);
  /** Danh sách nhóm cột — đổ vào dropdown "Nhóm cột". */
  readonly groups = input<HrmColumnGroup[]>([]);

  /** Nhãn i18n (mặc định tiếng Việt). */
  readonly emptyLabel = input('Chọn một cột để xem cấu hình.');
  readonly renameLabel = input('Đổi tên cột');
  readonly columnWordLabel = input('Cột');
  readonly displaySectionLabel = input('HIỂN THỊ');
  readonly positionSectionLabel = input('VỊ TRÍ');
  readonly widthLabel = input('Độ rộng');
  readonly alignLabel = input('Căn lề');
  readonly contentLabel = input('Nội dung');
  readonly formatLabel = input('Định dạng');
  readonly groupLabel = input('Nhóm cột');
  readonly pinLabel = input('Ghim');
  readonly autoLabel = input('Tự động');
  readonly autoByTypeLabel = input('theo kiểu dữ liệu');
  readonly noGroupLabel = input('Không thuộc nhóm');
  readonly alignAutoLabel = input('Tự động');
  readonly alignLeftLabel = input('Trái');
  readonly alignCenterLabel = input('Giữa');
  readonly alignRightLabel = input('Phải');
  readonly contentTruncateLabel = input('Cắt một dòng');
  readonly contentWrapLabel = input('Xuống dòng');
  readonly pinNoneLabel = input('Không');
  readonly pinLeftLabel = input('Trái');
  readonly pinRightLabel = input('Phải');

  protected readonly icPencil = IconPencil;
  protected readonly icChevron = IconChevronDown;

  /** Trạng thái UI nội bộ. */
  protected readonly fmtOpen = signal(false);
  protected readonly editingName = signal(false);
  protected readonly nameDraft = signal('');

  /** Các preset độ rộng cố định (giá trị '' = Tự động → lưu width=''). */
  private readonly widthPresets = ['120px', '160px', '200px', '240px'];

  /** Kiểu dữ liệu hiện tại (bỏ trống ⇒ 'text'). */
  protected readonly type = computed<HrmDataType>(() => this.column()?.type ?? 'text');
  /** Căn lề / nội dung / ghim đang chọn (kèm mặc định khi bỏ trống). */
  protected readonly align = computed<HrmColAlign>(() => this.column()?.align ?? 'auto');
  protected readonly content = computed<HrmColContent>(() => this.column()?.content ?? 'truncate');
  protected readonly pin = computed<HrmColPin>(() => this.column()?.pin ?? 'none');
  /** Giá trị width chuẩn hoá cho select ('' = Tự động; 'auto' quy về ''). */
  protected readonly widthValue = computed(() => {
    const w = this.column()?.width;
    return (!w || w === 'auto') ? '' : w;
  });
  /** groupId hiện tại ('' = không thuộc nhóm). */
  protected readonly groupValue = computed(() => this.column()?.groupId ?? '');

  /** Danh sách option độ rộng (Tự động đầu tiên; thêm giá trị lạ nếu đang dùng width ngoài preset). */
  protected readonly widthOptions = computed(() => {
    const opts = [{ value: '', label: this.autoLabel() }, ...this.widthPresets.map((p) => ({ value: p, label: p }))];
    const w = this.widthValue();
    if (w && !this.widthPresets.includes(w)) opts.splice(1, 0, { value: w, label: w });
    return opts;
  });

  /** Options Định dạng THEO KIỂU DỮ LIỆU + option "Tự động" (value '') ở đầu. */
  protected readonly formatOptions = computed(() => [
    { value: '', label: this.autoLabel(), sample: '' },
    ...HRM_FORMAT_OPTIONS[this.type()],
  ]);
  /** Option định dạng đang chọn (khớp column.format; bỏ trống ⇒ Tự động). */
  protected readonly currentFormat = computed(() => {
    const v = this.column()?.format ?? '';
    const opts = this.formatOptions();
    return opts.find((o) => o.value === v) ?? opts[0];
  });

  /** Từ mô tả kiểu dữ liệu cho dòng phụ "Cột <loại>". */
  protected readonly typeWord = computed(() => {
    switch (this.type()) {
      case 'number': return 'số';
      case 'money': return 'tiền';
      case 'date': return 'ngày';
      case 'percent': return 'phần trăm';
      case 'status': return 'trạng thái';
      case 'user': return 'người dùng';
      case 'boolean': return 'đúng/sai';
      default: return 'văn bản';
    }
  });
  /** Chú thích căn lề khi 'Tự động' — suy theo kiểu dữ liệu (hrmAutoAlign). */
  protected readonly autoAlignWord = computed(() => {
    switch (hrmAutoAlign(this.column()?.type)) {
      case 'right': return 'phải';
      case 'center': return 'giữa';
      default: return 'trái';
    }
  });

  /** Ghi 1 phần thay đổi vào column (two-way) — bỏ qua khi chưa chọn cột. */
  protected patch(p: Partial<HrmColumnDef>): void {
    const c = this.column();
    if (!c) return;
    this.column.set({ ...c, ...p });
  }

  /** Chọn định dạng ('' = Tự động) rồi đóng dropdown. */
  protected setFormat(value: string): void {
    this.patch({ format: value });
    this.fmtOpen.set(false);
  }

  /** Đổi tên cột inline. */
  protected startName(): void {
    this.nameDraft.set(this.column()?.title ?? '');
    this.editingName.set(true);
  }
  protected commitName(): void {
    if (!this.editingName()) return;
    const next = this.nameDraft().trim();
    if (next) this.patch({ title: next });
    this.editingName.set(false);
  }
  protected cancelName(): void { this.editingName.set(false); }
}
